#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

int best(const vector<int>& adj, int mask) {
    if (mask == 0) return 0;
    int v = __builtin_ctz(mask);
    int rest = mask & ~(1 << v);
    if ((adj[v] & rest) == 0) return 1 + best(adj, rest);
    return max(best(adj, rest), 1 + best(adj, rest & ~adj[v]));
}

